import { randomInt } from 'node:crypto';

// P-4e (DECIDED, AUTH-E2E final completion): temporary passwords are generated by IT tooling with a CSPRNG —
// 24 characters from ASCII letters, digits and shell/URL-safe symbols (no quotes, backslash, space, $ or backtick).
// crypto.randomInt draws each character uniformly (no modulo bias). 71^24 ≈ 2^147.
// The value is shown once to the operator, stored only as an Argon2id hash, never logged or written to a file.

export const TEMPORARY_PASSWORD_LENGTH = 24;
export const TEMPORARY_PASSWORD_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#%+-=?@_';

export function generateTemporaryPassword(): string {
  let value = '';
  for (let i = 0; i < TEMPORARY_PASSWORD_LENGTH; i++) value += TEMPORARY_PASSWORD_ALPHABET.charAt(randomInt(TEMPORARY_PASSWORD_ALPHABET.length));
  return value;
}
